itment", "Broad capability diversity covering industrial, architectural, and food-grade fabrication", "Single-source responsibility from design drafting through field installation"], "facts_used": ["Headquarters in Louisville, KY -> db", "Team formed by former GCH International, Harpring Inc., Griffin & Co employees -> /", "Services: sheet metal fabrication, structural components, architectural products, installation -> /", "24/7 installation services and off-hours shifts -> /", "Capabilities include CNC punching, welding, on-site polishing, storage tanks, vessels, structural steel, food-grade conveyors -> /, /services", "Industries served: food processing, food service, pharmaceutical, industrial, architectural -> /services", "Material: stainless steel (duct, PSS hoods, handrails) -> /services", "Equipment: CNC punch with dimple & louvered parts -> products", "Address: 4051 McCollum Ct., Louisville, KY 40218 -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "BGMW offers solutions in many facets of sheet metal fabrication, structural components, institutional architectural products, as well as installation services", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bluegrass-metal-works-inc' AND approved AND profile IS NULL;
