unds -> /", "Member-owned cooperative structure -> /", "Core principles: innovation, accountability, integrity, commitment to service -> /"], "company_type": "Other", "makes_products": "no", "type_evidence": "provides electric power to over 3,800 farm, residential, and commercial consumer-members", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='bon-homme-yankton-electric-association-inc' AND approved AND profile IS NULL;
